  const a=ring[i-1],b=ring[i];if(a.x===b.x&&a.y===b.y)continue;
  const edge={a,b,ringId,index:i-1,id:edges.length,minX:Math.min(a.x,b.x),maxX:Math.max(a.x,b.x),minY:Math.min(a.y,b.y),maxY:Math.max(a.y,b.y)};edges.push(edge);
  const from=Math.max(0,Math.floor(Math.min(a.y,b.y)/4)),to=Math.min(250,Math.floor(Math.max(a.y,b.y)/4));
