ASIA_WORLD.navigation=NAV_GRID;
const navBins=new Map();for(let i=0;i<NAV_GRID.cells.length;i++){if(!NAV_GRID.cells[i])continue;const p=navigationPoint(i),key=`${Math.floor(p.x/16)},${Math.floor(p.y/16)}`;if(!navBins.has(key))navBins.set(key,[]);navBins.get(key).push(i);}
export function nearestNavigationNode(point,component=null){if(!isOnLand(point))return null;const x=Math.floor(point.x/16),y=Math.floor(point.y/16);let best=null,distance=Infinity;for(let radius=0;radius<=16;radius++){for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){if(radius&&Math.abs(dx)!==radius&&Math.abs(dy)!==radius)continue;for(const i of navBins.get(`${x+dx},${y+dy}`)||[]){if(component!==null&&NAV_GRID.components[i]!==component)continue;const p=navigationPoint(i),d=Math.hypot(p.x-point.x,p.y-point.y);if(d<distance&&segmentOnLand(point,p)){best=i;distance=d;}}}if(best!==null&&radius*16>distance+16)break;}return best;}
function regionContains(p,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[j],b=poly[i];if((a.y>p.y)!==(b.y>p.y)&&p.x<(b.x-a.x)*(p.y-a.y)/(b.y-a.y)+a.x)inside=!inside;}return inside;}
export function regionAt(point){if(!isOnLand(point))return null;return [...ASIA_WORLD.regions].reverse().find(r=>(r.polygons||[r.polygon]).some(poly=>regionContains(point,poly))&&!(r.excludePolygons||[]).some(poly=>regionContains(point,poly)))||null;}
export function isOnPlayableLand(point){return nearestNavigationNode(point)!==null;}
export function portsForComponent(component){return ASIA_CITIES.filter(c=>c.port&&c.component===component);}
export function shippingLane(fromId,toId){const lane=ASIA_WORLD.shippingLanes.find(l=>l.fromId===fromId&&l.toId===toId||l.fromId===toId&&l.toId===fromId);return !lane?null:lane.fromId===fromId?lane:{...lane,fromId,toId,path:[...lane.path].reverse(),seaStart:lane.path.length-1-lane.seaEnd,seaEnd:lane.path.length-1-lane.seaStart};}
